styl:
.b-exnova-footer-19 .mar-mob, .b-exnova-footer-19 .socials a {  margin:0 10px  }
.b-exnova-footer-19 .socials {  display:block;font-size:0;margin:0 auto;text-align:center  }
.b-exnova-footer-19 .socials a {  display:inline-block;vertical-align:middle  }
@media screen and (max-width:600px) {
  .b-exnova-footer-19 .socials a {  margin-bottom:10px!important  }
}
.b-exnova-footer-19 .soc-icon {  float:none;max-width:40px  }
.b-exnova-footer-19 .ig {  max-width:24px;margin-left:6px  }
@media screen and (max-width:600px) {
  .b-exnova-footer-19 .ig {  width:24px!important  }
}
.b-exnova-footer-19 .twitter {  max-width:24px;margin:0 6px  }
@media screen and (max-width:600px) {
  .b-exnova-footer-19 .twitter {  width:24px!important  }
}
.b-exnova-footer-19 .fb {  max-width:24px;margin-right:6px  }
